            i = j
            continue
        raise _Err()
    tokens.append(("end", 0))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos][0]

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += [REDACTED]
        return tok

    # expr := term (('+' | '-') term)*
    def expr(self):
        value = self.term()
        while True:
            op = self.peek()
            if op == "+":
                self.pos += [REDACTED]
                value = _wrap(value + self.term())
            elif op == "-":
                self.pos += [REDACTED]
                value = _wrap(value - self.term())
            else:
                return value

    # term := factor (('*' | '/' | '%') factor)*
    def term(self):
        value = self.factor()
        while True:
            op = self.peek()
            if op == "*":
                self.pos += [REDACTED]
                value = _wrap(value * self.factor())
            elif op == "/":
                self.pos += [REDACTED]
                value = _div(value, self.factor())
            elif op == "%":
                self.pos += [REDACTED]
                value = _rem(value, self.factor())
            else:
                return value

    # factor := unary ('^' unary)*   -- left associative
    def factor(self):
        value = self.unary()
        while self.peek() == "^":
            self.pos += [REDACTED]
            value = _pow(value, self.unary())
        return value

    # unary := ('+' | '-')* primary
